$ErrorActionPreference = "Stop"

$ROOT = "C:\Users\santi\OneDrive\Escritorio\ALPHA_ENGINE_PRODUCTION"
$REC  = Join-Path $ROOT "ALPHA_ENGINE_DATA_RECOVERY_V1"
$V13  = Join-Path $ROOT "ALPHA_ENGINE_V13_RETURN_FIRST_MULTI_HORIZON"
$WEB  = Join-Path $ROOT "web\v4"

$SERVER = Join-Path $ROOT "web\run_alpha_engine_v4.py"
$APP    = Join-Path $WEB "app.js"
$INDEX  = Join-Path $WEB "index.html"
$CSS    = Join-Path $WEB "styles.css"
$BUILDER= Join-Path $REC "scripts\build_forward_nav_v42.py"
$SMOKE  = Join-Path $REC "scripts\smoke_v42.py"
$START  = Join-Path $ROOT "START_ALPHA_ENGINE_V4.ps1"

Write-Host ""
Write-Host "================================================================"
Write-Host "ALPHA ENGINE V4.2 - FINAL AUTOMATION LAYER"
Write-Host "AUTO MARKET / CAUSAL FORWARD NAV / RECOMMENDATIONS"
Write-Host "NO LLM / NO SHEETS / NO SEALED V13 MUTATION"
Write-Host "================================================================"

foreach($p in @($ROOT,$V13,$SERVER,$APP,$INDEX,$CSS,$START)) {
    if(-not(Test-Path $p)) { throw "Missing required path: $p" }
}

function Write-B64File([string]$Path,[string]$B64) {
    $parent=Split-Path -Parent $Path
    if($parent){New-Item -ItemType Directory -Force -Path $parent|Out-Null}
    [IO.File]::WriteAllBytes($Path,[Convert]::FromBase64String($B64))
}

Write-Host ""
Write-Host "[1/9] SEALED V13 IMMUTABILITY SNAPSHOT"
$critical=@(
  "outputs\v13_phase2r_model_spec.json",
  "outputs\v13_phase2u_expert_evidence.csv",
  "outputs\v13_phase3aa_freeze_manifest.json",
  "outputs\v13_phase4_sealed_features.csv",
  "outputs\v13_phase4_model_seal_manifest.json",
  "outputs\v13_phase4_sealed_model_bundle.joblib"
)
$before=@{}
foreach($rel in $critical){
    $p=Join-Path $V13 $rel
    if(-not(Test-Path $p)){throw "Critical V13 file missing: $p"}
    $before[$rel]=(Get-FileHash -Algorithm SHA256 $p).Hash
}
Write-Host "  PASS 6/6"

Write-Host ""
Write-Host "[2/9] BACKUP V4.1"
$stamp=Get-Date -Format "yyyyMMdd_HHmmss"
$backup=Join-Path $REC "outputs\data_recovery_v1\web_backups\v42_$stamp"
New-Item -ItemType Directory -Force -Path $backup|Out-Null
Copy-Item $SERVER (Join-Path $backup "run_alpha_engine_v4.py") -Force
Copy-Item $APP (Join-Path $backup "app.js") -Force
Copy-Item $INDEX (Join-Path $backup "index.html") -Force
Copy-Item $CSS (Join-Path $backup "styles.css") -Force
Write-Host "  PASS $backup"

Write-Host ""
Write-Host "[3/9] INSTALL V4.2"
Write-B64File $SERVER ""
Write-B64File $APP ""
Write-B64File $INDEX ""
Write-B64File $CSS ""
Write-B64File $BUILDER ""
Write-B64File $SMOKE ""

python -c "from pathlib import Path; paths=[r'$SERVER',r'$BUILDER',r'$SMOKE']; [compile(Path(p).read_text(encoding='utf-8'),p,'exec') for p in paths]; print('  Python syntax PASS')"
if($LASTEXITCODE -ne 0){throw "V4.2 Python syntax failed"}
Write-Host "  PASS"

Write-Host ""
Write-Host "[4/9] BUILD CAUSAL FORWARD NAV"
Set-Location $ROOT
python $BUILDER
if($LASTEXITCODE -ne 0){
    throw "Forward NAV failed its causal/parity gate. Nothing sealed was changed."
}
Write-Host "  PASS"

Write-Host ""
Write-Host "[5/9] STOP V4.1"
$listeners=@(Get-NetTCPConnection -LocalPort 8765 -State Listen -ErrorAction SilentlyContinue)
foreach($l in $listeners){
    $proc=Get-CimInstance Win32_Process -Filter "ProcessId=$($l.OwningProcess)" -ErrorAction SilentlyContinue
    if($proc -and [string]$proc.CommandLine -like "*run_alpha_engine_v4.py*"){
        Stop-Process -Id $l.OwningProcess -Force
        Write-Host "  stopped PID=$($l.OwningProcess)"
    } else {
        throw "Port 8765 occupied by non-Alpha process. Nothing killed."
    }
}
Start-Sleep -Milliseconds 800
Write-Host "  PASS"

Write-Host ""
Write-Host "[6/9] START V4.2"
$launcher=Start-Process -FilePath "powershell.exe" -ArgumentList @(
    "-NoProfile","-ExecutionPolicy","Bypass","-File",$START
) -WindowStyle Hidden -PassThru
Write-Host "  launcher PID=$($launcher.Id)"

$ready=$false
for($i=0;$i -lt 40;$i++){
    Start-Sleep -Milliseconds 750
    try{
        $h=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/health" -TimeoutSec 5
        if($h.status -eq "PASS" -and $h.version -eq "V4.2"){$ready=$true;break}
    }catch{}
}
if(-not $ready){throw "V4.2 server did not become ready"}

Write-Host ""
Write-Host "[7/9] MARKET + EXCEL INITIAL SYNC"
$mr=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/market/refresh" -Method Post -ContentType "application/json" -Body "{}" -TimeoutSec 700
if($mr.status -notin @("PASS","BUSY")){throw "Initial market refresh failed: $($mr.status)"}
Write-Host "  market status: $($mr.status)"

# Rebuild Excel from current authoritative ledger by re-saving its existing JSON through
# the server lifecycle. Market refresh already triggers this on PASS.
if(-not(Test-Path (Join-Path $ROOT "PRODUCT\AlphaEngine_Cartera_Real.xlsx"))){
    throw "AlphaEngine_Cartera_Real.xlsx was not created"
}
Write-Host "  PASS"

Write-Host ""
Write-Host "[8/9] FULL PRODUCT SMOKE"
python $SMOKE
if($LASTEXITCODE -ne 0){throw "V4.2 product smoke failed. V13 remains untouched."}

$marketJob=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/market/job" -TimeoutSec 40
$forwardJob=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/forward/job" -TimeoutSec 40
$forwardNav=Invoke-RestMethod -Uri "http://127.0.0.1:8765/api/v4/forward/nav" -TimeoutSec 40

Write-Host "  market auto     : every $($marketJob.refresh_every_seconds)s / regular only"
Write-Host "  model session   : $($forwardJob.current_model_session)"
Write-Host "  market session  : $($forwardJob.latest_completed_market_session)"
Write-Host "  forward stale   : $($forwardJob.stale)"
Write-Host "  forward NAV     : $($forwardNav.start_date) -> $($forwardNav.latest_date)"
Write-Host "  parity          : $($forwardNav.holdout_parity.status)"

if($forwardJob.stale -eq $true){throw "Forward unexpectedly stale after V4.2 install"}
if($forwardNav.status -ne "PASS"){throw "Forward NAV is not PASS"}
if($forwardNav.holdout_parity.status -ne "PASS"){throw "Forward NAV parity not PASS"}

Write-Host ""
Write-Host "[9/9] SEALED V13 IMMUTABILITY VERIFY"
foreach($rel in $critical){
    $p=Join-Path $V13 $rel
    $after=(Get-FileHash -Algorithm SHA256 $p).Hash
    if($after -ne $before[$rel]){throw "SEALED V13 MUTATION DETECTED: $rel"}
}
Write-Host "  PASS 6/6 byte-identical"

Write-Host ""
Write-Host "================================================================"
Write-Host "ALPHA ENGINE V4.2: PASS"
Write-Host "================================================================"
Write-Host "MARKET AUTO        : 5 MIN / REGULAR SESSION ONLY"
Write-Host "FORWARD AUTO       : LATEST COMPLETED SESSION"
Write-Host "FORWARD NAV        : 2026-09-04 -> LATEST / CAUSAL / FROZEN COST"
Write-Host "PARITY GATE        : SEALED HOLDOUT REPRODUCED"
Write-Host "RECOMMENDATIONS    : TARGETS + PERSONAL NOMINALS WHEN LEDGER LOADED"
Write-Host "EXCEL              : 7 SHEETS INCLUDING RECOMENDACIONES"
Write-Host "LLM                : PAUSED"
Write-Host "REAL ORDERS        : NO"
Write-Host "V13 SEALED CORE    : UNCHANGED"
Write-Host "================================================================"

Start-Process "http://127.0.0.1:8765/"
